import json
import pandas as pd

text = ('[{"id": 1, "city": "Gaza", "rent": 590, '
        '"landlord": {"name": "Abu Ahmad", "verified": true}}, '
        '{"id": 2, "city": "Rafah", "rent": 285}]')
records = json.loads(text)


def flatten(d, prefix=""):
    flat = {}
    for key, value in d.items():
        name = prefix + key
        if isinstance(value, dict):
            flat.update(flatten(value, name + "_"))
        else:
            flat[name] = value
    return flat


rows = []
for rec in records:
    rows.append(flatten(rec))

table = pd.DataFrame(rows)
print(table)
